import csv
import io
import re


def parse_csv(raw_csv: str):
    reader = csv.reader(
        io.StringIO(raw_csv.lstrip("\ufeff"), newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )
    parsed = [row for row in reader if row and any(value != "" for value in row)]

    header_index = next(
        (index for index, row in enumerate(parsed) if len(row) == 4),
        None,
    )

    if header_index is None:
        if not parsed:
            return {"columns": [], "rows": []}
        columns = [f"column_{index + 1}" for index in range(len(parsed[0]))]
        data = parsed[1:]
    else:
        columns = parsed[header_index]
        if columns:
            columns[0] = columns[0].lstrip("\ufeff")
        data = parsed[header_index + 1:]

    width = len(columns)
    rows = []
    for row in data:
        if len(row) < width:
            row = row + [""] * (width - len(row))
        elif len(row) > width and width:
            row = row[:width - 1] + [",".join(row[width - 1:])]
        rows.append(row)

    return {"columns": columns, "rows": rows}
